package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_max_TriageGen5Test {

    @Test
    public void testMax_AIsSmallerThanB() {
        // Tests the (a <= b) branch where a < b
        float a = 1.0f;
        float b = 2.0f;
        float expected = 2.0f;
        assertEquals(expected, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_AIsEqualToBe() {
        // Tests the (a <= b) branch where a == b
        float a = 5.0f;
        float b = 5.0f;
        float expected = 5.0f;
        assertEquals(expected, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_AIsGreaterThanB_Normal() {
        // Tests the (a <= b) is false branch, and (Float.isNaN(a + b)) is false
        // Note: The method logic provided is: (a <= b) ? b : (Float.isNaN(a + b) ? Float.NaN : b);
        // This logic implies if a > b, it returns b unless a + b is NaN.
        // This is a highly unusual max implementation, but we test according to the provided code.
        float a = 10.0f;
        float b = 2.0f;
        float expected = 2.0f; 
        assertEquals(expected, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_AIsGreaterThanB_NaNResult() {
        // Tests the (a <= b) is false branch, and (Float.isNaN(a + b)) is true
        // To make a + b NaN where a > b:
        // If a is Infinity and b is -Infinity, a + b is NaN.
        float a = Float.POSITIVE_INFINITY;
        float b = Float.NEGATIVE_INFINITY;

        // Check condition: (a <= b) -> (Inf <= -Inf) is false.
        // Check condition: Float.isNaN(a + b) -> Float.isNaN(Inf + -Inf) -> Float.isNaN(NaN) is true.
        // Result should be NaN.
        float result = FastMath.max(a, b);
        assertTrue(Float.isNaN(result));
    }

    @Test
    public void testMax_WithNaN() {
        // Test behavior when one input is NaN
        // If a is NaN, (a <= b) is false.
        // If a is NaN, a + b is NaN.
        // Result should be NaN.
        float a = Float.NaN;
        float b = 1.0f;
        float result = FastMath.max(a, b);
        assertTrue(Float.isNaN(result));
    }

    @Test
    public void testMax_WithBothNaN() {
        float a = Float.NaN;
        float b = Float.NaN;
        float result = FastMath.max(a, b);
        assertTrue(Float.isNaN(result));
    }
}
